type Answers = ReturnType<typeof answers>;

/** In-memory synthetic adapter. Every method is local; nothing leaves the browser. */
export function createSyntheticA2pAdapter(scenario: A2pSyntheticScenario = 'ready', options: { delayMs?: number } = {}): A2pRegistrationAdapter {
  const delay = options.delayMs ?? 0;
  const wait = () => new Promise<void>((done) => { setTimeout(done, delay); });
  const state = { findings: findings(), answers: null as Answers | null, polls: 0, checkUrl: A2P_SYNTHETIC_SCHOOL.website as string, started: scenario === 'checking' };
  const check = () => {
    if (scenario === 'checking') return { checkId: 'syn-check-1', state: 'CHECKING', websiteUrl: state.checkUrl, pagesChecked: 2, pagesPlanned: 6 };
    if (state.polls < 2) return { checkId: 'syn-check-1', state: state.polls === 0 ? 'QUEUED' : 'CHECKING', websiteUrl: state.checkUrl, pagesChecked: state.polls * 3, pagesPlanned: 6 };
    return { checkId: 'syn-check-1', state: 'COMPLETED', websiteUrl: state.checkUrl, pagesChecked: 6, pagesPlanned: 6, completedAt: OBSERVED, findings: state.findings };
  };
  return {
    source: 'SYNTHETIC_FIXTURE',
    async availability(): Promise<A2pAvailability> {
      await wait();
      if (scenario === 'error') return { state: 'ERROR' };
      return { state: 'READY', source: 'SYNTHETIC_FIXTURE', capabilities: { websiteCheck: true, findingReview: true, answerDrafts: true, saveAnswers: true, ownerConfirmations: true, registrationStatus: true, assistant: false } };
    },
    async latestWebsiteCheck() { await wait(); return state.started ? check() : null; },
    async startWebsiteCheck(websiteUrl: string) {
      await wait();
      state.started = true; state.polls = 0; state.checkUrl = websiteUrl; state.findings = findings();
      if (scenario === 'check-failed') return { checkId: 'syn-check-1', state: 'FAILED', websiteUrl, pagesChecked: 0, pagesPlanned: null };
      return check();
    },
    async readWebsiteCheck() { await wait(); state.polls += 1; return check(); },
    async markFinding(findingId: string, review: A2pReviewMark) {
      await wait();
      const finding = state.findings.find((item) => item.id === findingId);
      if (!finding) throw new Error('Unknown synthetic finding.');
      finding.review = review;
      return { ...finding };
    },
    async draftAnswers() { await wait(); state.answers = answers(); return state.answers; },
    async saveAnswers(values: ReadonlyArray<{ key: A2pAnswerKey; value: string }>, expectedRevision: number | null) {
      await wait();
      const current = state.answers ?? answers();
      if (expectedRevision !== current.revision) throw new Error('Synthetic revision conflict.');
      const next = { ...current, revision: current.revision + 1, answers: current.answers.map((answer) => {
        const edited = values.find((value) => value.key === answer.key);
        return edited && edited.value !== answer.value ? { ...answer, value: edited.value, provenance: 'UNVERIFIED_DRAFT', notes: ['Edited by the owner. Not verified against the website.'] } : answer;
      }) };
      state.answers = next;
      return next;
    },
    async setConfirmation(key: A2pConfirmationKey, confirmed: boolean) {
      await wait();
      const current = state.answers ?? answers();
      const others = current.confirmations.filter((item) => item.key !== key);
      state.answers = { ...current, revision: current.revision + 1, confirmations: confirmed ? [...others, { key, confirmed: true, confirmedAt: new Date().toISOString() }] : others };
      return state.answers;
    },
    async registrationStatus() { await wait(); return { status: 'DRAFT', reportedAt: null, providerReference: null, reasons: [] }; },
  };
}
